 static string ArchiveLabel(string key){switch(key){case "memoryUsed":return "已用内存";case "memoryAvailable":return "可用内存";case "vramUsed":return "已用显存";case "vramTotal":return "显存总量";case "vram":return "显存占用";case "diskTemp":return "磁盘温度";case "diskRead":return "磁盘读取";case "diskWrite":return "磁盘写入";case "frequency":return "CPU频率";case "download":return "下载速率";case "upload":return "上传速率";default:return MonitorEngine.Label(key);}}
