 void BuildArchivePage(){var nav=new WrapPanel{Margin=new Thickness(0,0,0,12)};var host=new ContentControl{HorizontalContentAlignment=HorizontalAlignment.Stretch};content.Children.Add(nav);content.Children.Add(host);var links=new Dictionary<string,Button>();Action<string> select=name=>{archiveTab=name;archivePlot=null;archiveDonut=null;host.Content=BuildArchiveSection(name);foreach(var pair in links)pair.Value.Tag=pair.Key==name?"selected":null;TerminalAppearance.BindTree(host);VisualEffects.Apply(host);RefreshArchive(true);};foreach(string title in new[]{"网络流量","直连与代理","资源占用","温度记录","资源容量","速率与频率","Codex用量","额度轨迹","采集与来源"}){string name=title;links[name]=Button(nav,name,()=>select(name));}select(archiveTab);}
 FrameworkElement BuildArchiveSection(string name){StackPanel body;var frame=Panel(name=="采集与来源"?"档案来源与隐私":name+" · 历史线索","network",out body);if(name=="采集与来源"){BuildArchiveSources(body);return frame;}if(name=="网络流量"){BuildTrafficHistory(body);archiveDonut=new ArchiveDonut{Caption="收发占比",Unit="字节"};body.Children.Add(archiveDonut);return frame;}
  bool timeline=ArchiveTimelineTab(name);var timing=new WrapPanel();body.Children.Add(timing);
  if(timeline){var periodButtons=new List<Button>();foreach(var option in new[]{new{Caption="按日",Range=0},new{Caption="按周",Range=1},new{Caption="按月",Range=2}}){int range=option.Range;var button=Button(timing,option.Caption,()=>{archiveRange=range;for(int i=0;i<periodButtons.Count;i++)periodButtons[i].Tag=i==archiveRange?"selected":null;RefreshArchive(true);});button.Tag=archiveRange==range?"selected":null;periodButtons.Add(button);}}else{Button(timing,"按周",()=>{archiveMonth=false;RefreshArchive(true);});Button(timing,"按月",()=>{archiveMonth=true;RefreshArchive(true);});}
  Button(timing,"← 上一期",()=>{archiveDay=timeline?(archiveRange==0?archiveDay.AddDays(-1):archiveRange==1?archiveDay.AddDays(-7):archiveDay.AddMonths(-1)):(archiveMonth?archiveDay.AddMonths(-1):archiveDay.AddDays(-7));archiveDate.SelectedDate=archiveDay;RefreshArchive(true);});Button(timing,"◎ 定位当前周期",()=>{archiveDay=DateTime.Today;archiveDate.SelectedDate=archiveDay;RefreshArchive(true);if(archiveDates.Length>0)LocateTimeline(archivePlot,archiveDates[0],archiveDates[archiveDates.Length-1].AddMinutes(ArchiveTimelineTab(archiveTab)?archiveStepMinutes:1440));});Button(timing,"下一期 →",()=>{archiveDay=timeline?(archiveRange==0?archiveDay.AddDays(1):archiveRange==1?archiveDay.AddDays(7):archiveDay.AddMonths(1)):(archiveMonth?archiveDay.AddMonths(1):archiveDay.AddDays(7));archiveDate.SelectedDate=archiveDay;RefreshArchive(true);});archiveDate=TaskbarName(new DatePicker{SelectedDate=archiveDay,Width=200,SelectedDateFormat=DatePickerFormat.Short,Margin=new Thickness(0,4,8,4)},"档案日期");archiveDate.Resources[typeof(System.Windows.Controls.Primitives.DatePickerTextBox)]=new Style(typeof(System.Windows.Controls.Primitives.DatePickerTextBox),TryFindResource(typeof(TextBox)) as Style);archiveDate.SetResourceReference(Control.BackgroundProperty,"DeskBase");archiveDate.SetResourceReference(Control.ForegroundProperty,"DeskText");timing.Children.Add(archiveDate);archiveDate.SelectedDateChanged+=(s,e)=>{if(archiveDate.SelectedDate.HasValue){archiveDay=archiveDate.SelectedDate.Value;RefreshArchive(true);}};
  if(timeline){var resolution=new WrapPanel();body.Children.Add(resolution);resolution.Children.Add(Text("时间粒度",12));var steps=new[]{1,5,60,1440};var stepButtons=new List<Button>();foreach(var option in new[]{new{Caption="1分钟",Minutes=1},new{Caption="5分钟",Minutes=5},new{Caption="1小时",Minutes=60},new{Caption="1天",Minutes=1440}}){int minutes=option.Minutes;var button=Button(resolution,option.Caption,()=>{archiveStepMinutes=minutes;for(int i=0;i<stepButtons.Count;i++)stepButtons[i].Tag=steps[i]==minutes?"selected":null;RefreshArchive(true);});button.Tag=archiveStepMinutes==minutes?"selected":null;stepButtons.Add(button);}SettingDescription(body,"从启用后每分钟采样；5分钟按采样汇总，空白代表无记录。旧数据只有小时汇总，无法还原分钟变化。");}
  var layers=new WrapPanel();body.Children.Add(layers);archiveBars=assistant.Config.Monitor.ArchiveBars;archiveLines=assistant.Config.Monitor.ArchiveLines;var bars=TaskbarCheck(layers,"叠加柱状图",archiveBars);var lines=TaskbarCheck(layers,"叠加折线图",archiveLines);var fit=TaskbarCheck(layers,"适应窗口宽度",archiveFit);fit.Click+=(s,e)=>{archiveFit=fit.IsChecked==true;RefreshArchive(true);};bars.Click+=(s,e)=>{archiveBars=bars.IsChecked==true;SaveMonitor(()=>assistant.Config.Monitor.ArchiveBars=archiveBars);RefreshArchive(true);};lines.Click+=(s,e)=>{archiveLines=lines.IsChecked==true;SaveMonitor(()=>assistant.Config.Monitor.ArchiveLines=archiveLines);RefreshArchive(true);};
  string[] keys=name=="资源容量"?new[]{"memoryUsed","memoryAvailable","vramUsed","vramTotal"}:name=="资源占用"?ResourceKeys:name=="温度记录"?TemperatureKeys:name=="速率与频率"?RateKeys:name=="额度轨迹"?new[]{"codex5h","codex7d"}:new string[0];if(keys.Length>0){var choose=new WrapPanel();body.Children.Add(choose);if(!keys.Any(archiveMetrics.Contains)){archiveMetrics.Clear();foreach(string key in keys.Where(k=>k!="frequency"))archiveMetrics.Add(key);}foreach(string key in keys){string metric=key;var box=TaskbarCheck(choose,ArchiveLabel(key),archiveMetrics.Contains(key));box.Click+=(s,e)=>{if(box.IsChecked==true){if(metric=="frequency")archiveMetrics.Clear();else archiveMetrics.Remove("frequency");archiveMetrics.Add(metric);}else archiveMetrics.Remove(metric);BuildArchiveReload();};}var peak=TaskbarCheck(layers,"查看峰值（关闭为加权均值）",archivePeak);peak.Click+=(s,e)=>{archivePeak=peak.IsChecked==true;RefreshArchive(true);};}
  archiveSummary=Text("",16);archiveSource=Text("",12);body.Children.Add(archiveSummary);body.Children.Add(archiveSource);archivePlot=new ArchivePlot();var archiveViewer=new ScrollViewer{Content=archivePlot,HorizontalScrollBarVisibility=ScrollBarVisibility.Auto,VerticalScrollBarVisibility=ScrollBarVisibility.Disabled};AddTimelineZoom(body,archivePlot,archiveViewer,"历史图表");body.Children.Add(archiveViewer);archiveDonut=new ArchiveDonut();body.Children.Add(archiveDonut);Button(body,"导出当前图表CSV",ExportArchive);return frame;
