 void BuildArchiveReload(){ShowPage("线索档案馆");}
 void RefreshArchive(bool force=false){if(!force&&(DateTime.UtcNow-lastArchiveUi).TotalSeconds<5)return;lastArchiveUi=DateTime.UtcNow;if(archiveTab=="网络流量"){RefreshTrafficHistory();if(archiveDonut!=null&&trafficChart!=null)archiveDonut.Slices=new[]{new ArchiveSlice{Label="下载",Color="#45AED6",Value=trafficDown?trafficChart.Points.Sum(p=>p.Download):0},new ArchiveSlice{Label="上传",Color="#9B80E1",Value=trafficUp?trafficChart.Points.Sum(p=>p.Upload):0}};if(archiveDonut!=null)archiveDonut.InvalidateVisual();return;}if(archiveTab=="采集与来源")return;if(archivePlot==null)return;
  bool timeline=ArchiveTimelineTab(archiveTab);DateTime start=timeline?ArchiveTimeline.Start(archiveDay,archiveRange):TrafficHistory.Start(archiveDay,archiveMonth),end=timeline?ArchiveTimeline.End(start,archiveRange):archiveMonth?start.AddMonths(1):start.AddDays(7);archiveDates=timeline?ArchiveTimeline.Dates(start,end,archiveStepMinutes):Enumerable.Range(0,(end-start).Days).Select(i=>start.AddDays(i)).ToArray();ArchiveHour[] hours=assistant.Archive.Range(start,end);MinutePoint[] minutes=timeline?assistant.MinuteHistory.Range(start,end):new MinutePoint[0];var colors=new[]{"#55BCE4","#82CC76","#BA9CEA","#F7BB67","#EE8296"};var list=new List<ArchiveSeries>();archiveDonut.Slices=new ArchiveSlice[0];string note="",unit="";if(archiveTab=="Codex用量"){var days=assistant.TokenHistory.Range(start,end);unit="token";for(int i=0;i<3;i++){int k=i;list.Add(new ArchiveSeries{Label=new[]{"非缓存输入","缓存输入","输出"}[i],Color=colors[i],Values=archiveDates.Select(date=>{var d=days.FirstOrDefault(x=>x.Day==date.ToString("yyyy-MM-dd"));return d==null?(double?)null:k==0?Math.Max(0,d.Input-d.Cached):k==1?d.Cached:d.Output;}).ToArray()});}long total=days.Sum(d=>d.Total);archiveSummary.Text="本期记录 "+total.ToString("N0")+" token · 推理输出 "+days.Sum(d=>d.Reasoning).ToString("N0")+"（已包含在输出中）";archiveDonut.Caption="token构成";archiveDonut.Unit="token";archiveDonut.Slices=new[]{new ArchiveSlice{Label="非缓存输入",Color=colors[0],Value=days.Sum(d=>Math.Max(0,d.Input-d.Cached))},new ArchiveSlice{Label="缓存输入",Color=colors[1],Value=days.Sum(d=>d.Cached)},new ArchiveSlice{Label="输出",Color=colors[2],Value=days.Sum(d=>d.Output)}};note=assistant.TokenHistory.Status+"。本地日志记录值，不等于账单或额度百分比；缺失日志/额外压缩用量可能未计入。";
  }else if(archiveTab=="直连与代理"){unit="MiB";for(int i=0;i<3;i++){int k=i;list.Add(new ArchiveSeries{Label=new[]{"直连","代理","未分类"}[i],Color=colors[i],Values=archiveDates.Select(date=>{var b=hours.Where(h=>h.Utc.ToLocalTime().Date==date&&h.SplitRecorded).ToArray();return b.Length==0?(double?)null:b.Sum(h=>k==0?h.DirectDownload+h.DirectUpload:k==1?h.ProxyDownload+h.ProxyUpload:h.Unclassified)/1048576;}).ToArray()});}archiveSummary.Text="FlClash / Clash 内核的收发流量 · 非网卡总量、非国内/境外判定";archiveDonut.Caption="分流占比";archiveDonut.Unit="MiB";archiveDonut.Slices=list.Select(s=>new ArchiveSlice{Label=s.Label,Color=s.Color,Value=s.Values.Where(v=>v.HasValue).Sum(v=>v.Value)}).ToArray();note=assistant.SplitHistory.Status+"。仅观察连接字节增量；短连接等不能归类的差额单列，不按比例猜测。";
  }else{string[] keys=archiveTab=="资源容量"?new[]{"memoryUsed","memoryAvailable","vramUsed","vramTotal"}:archiveTab=="资源占用"?ResourceKeys:archiveTab=="温度记录"?TemperatureKeys:archiveTab=="额度轨迹"?new[]{"codex5h","codex7d"}:RateKeys;keys=keys.Where(archiveMetrics.Contains).ToArray();unit=archiveTab=="资源容量"?"GiB":archiveTab=="温度记录"?"°C":archiveTab=="速率与频率"?(keys.Contains("frequency")?"MHz":"MiB/s"):"%";for(int i=0;i<keys.Length;i++){string key=keys[i];list.Add(new ArchiveSeries{Label=ArchiveLabel(key),Color=colors[i%colors.Length],Values=ArchiveTimeline.Values(archiveDates,archiveStepMinutes,key,minutes,hours,archivePeak)});}archiveSummary.Text=(archiveTab=="额度轨迹"?"每个时间段最后一次有效额度":archivePeak?"时间段采样峰值":"时间段采样均值")+" · "+start.ToString("yyyy-MM-dd")+" — "+end.AddDays(-1).ToString("yyyy-MM-dd");note="分钟曲线从新版开始记录；旧数据仅有小时加权均值，5分钟视图留空，较粗粒度可回看旧记录。额度缺失不会补零，旧小时额度显示小时均值。";if(archiveTab=="资源占用"&&keys.Length>0){string key=keys[0];var metrics=hours.Where(h=>h.Metrics.ContainsKey(key)).Select(h=>h.Metrics[key]).ToArray();archiveDonut.Caption=ArchiveLabel(key)+"时长";archiveDonut.Unit="秒";archiveDonut.Slices=new[]{new ArchiveSlice{Label="低于40%",Color="#55BCE4",Value=metrics.Sum(m=>m.LowSeconds)},new ArchiveSlice{Label="40–80%",Color="#F7BB67",Value=metrics.Sum(m=>m.MidSeconds)},new ArchiveSlice{Label="80%以上",Color="#EE8296",Value=metrics.Sum(m=>m.HighSeconds)}};}else if(archiveTab=="温度记录"&&keys.Length>0){double recorded=hours.Where(h=>h.Metrics.ContainsKey(keys[0])).Sum(h=>h.Metrics[keys[0]].Weight),all=hours.Where(h=>h.Metrics.ContainsKey("cpu")).Sum(h=>h.Metrics["cpu"].Weight);archiveDonut.Caption="来源覆盖";archiveDonut.Unit="秒";archiveDonut.Slices=new[]{new ArchiveSlice{Label="有温度读数",Color="#55BCE4",Value=recorded},new ArchiveSlice{Label="缺失读数",Color="#718096",Value=Math.Max(0,all-recorded)}};}}
  archiveSource.Text=note;archiveSeries=list.ToArray();archivePlot.Dates=archiveDates;archivePlot.Series=archiveSeries;archivePlot.Unit=unit;archivePlot.StepMinutes=timeline?archiveStepMinutes:1440;CodexQuotaReset[] resetCopy;lock(assistant)resetCopy=(assistant.Config.Monitor.Quota.ResetHistory??new List<CodexQuotaReset>()).ToArray();archivePlot.Markers=archiveTab=="额度轨迹"?QuotaAudit.WithLegacy(assistant.QuotaReader.Audit==null?new QuotaAuditEvent[0]:assistant.QuotaReader.Audit.Between(start,end),resetCopy,start,end).Where(e=>e.Kind=="reset-observed"&&((e.Windows=="五小时"&&archiveMetrics.Contains("codex5h"))||(e.Windows=="周额度"&&archiveMetrics.Contains("codex7d")))).ToArray():new QuotaAuditEvent[0];archivePlot.ShowTime=timeline&&archiveStepMinutes<1440;archivePlot.Bars=archiveBars;archivePlot.Lines=archiveLines;archivePlot.Maximum=unit=="%"?(double?)100:null;archivePlot.MinWidth=archiveFit?650:Math.Max(650,archiveDates.Length*48+84);archivePlot.InvalidateVisual();archiveDonut.Visibility=archiveDonut.Slices.Length>0?Visibility.Visible:Visibility.Collapsed;archiveDonut.InvalidateVisual();
