 void ExportArchive(){using(var picker=new System.Windows.Forms.SaveFileDialog{Filter="CSV|*.csv",FileName="柯南线索档案.csv"})if(picker.ShowDialog()==System.Windows.Forms.DialogResult.OK){var rows=new List<string>{"日期,"+String.Join(",",archiveSeries.Select(s=>s.Label+"("+archivePlot.Unit+")"))};for(int i=0;i<archiveDates.Length;i++){int index=i;rows.Add((archivePlot.ShowTime?archiveDates[i].ToString("yyyy-MM-dd HH:mm"):archiveDates[i].ToString("yyyy-MM-dd"))+","+String.Join(",",archiveSeries.Select(s=>s.Values[index].HasValue?s.Values[index].Value.ToString("0.######",CultureInfo.InvariantCulture):"")));}File.WriteAllLines(picker.FileName,rows,new System.Text.UTF8Encoding(true));}}
 void BuildArchiveSources(Panel body){var cfg=assistant.Config.Monitor;SettingsLabel(body,"本机资源历史","CPU、内存、磁盘等由程序自动采样，开启后从现在开始积累。");MonitorToggle(body,"积累本机监控历史",()=>cfg.CollectHistory,v=>cfg.CollectHistory=v);SettingsLabel(body,"Codex 本地用量","目录留空会自动查找；这里只汇总日志中的统计字段。");MonitorToggle(body,"读取本地Codex token用量事件",()=>cfg.CodexUsageHistory,v=>cfg.CodexUsageHistory=v);var codex=TaskbarInput(body,"Codex日志目录",cfg.HistoryCodexHome,330);Button(body,"选择Codex数据目录…",()=>{using(var picker=new System.Windows.Forms.FolderBrowserDialog())if(picker.ShowDialog()==System.Windows.Forms.DialogResult.OK)codex.Text=picker.SelectedPath;});var tokenState=Text(assistant.TokenHistory.Status,12);body.Children.Add(tokenState);Button(body,"保存并读取本地用量",async()=>{string source=codex.Text.Trim();if(source.Length>0&&(!Path.IsPathRooted(source)||source.StartsWith(@"\\")||!Directory.Exists(source)))throw new ArgumentException("请选择存在的本地Codex数据目录。");SaveMonitor(()=>cfg.HistoryCodexHome=source);tokenState.Text="正在后台增量读取用量事件…";await System.Threading.Tasks.Task.Run(()=>assistant.TokenHistory.Scan(source.Length==0?cfg.Quota.Home:source));tokenState.Text=assistant.TokenHistory.Status;});
  SettingDescription(body,"只汇总本地用量事件，不保存提示词、回复或工具内容，不读取登录令牌。输入包含缓存输入；图表将非缓存输入、缓存输入、输出拆分，推理输出已含在输出中，不再次相加。历史数据在稳定用户目录，不随程序包带走。");
  SettingsLabel(body,"Clash 直连与代理统计","需要 FlClash 的统计控制接口。代理端口（例如7890）不能作为统计接口。");MonitorToggle(body,"统计Clash直连与代理流量",()=>cfg.ClashHistory,v=>{cfg.ClashHistory=v;assistant.SplitHistory.Reset();});var address=TaskbarInput(body,"本机控制接口",cfg.ClashController,280);var password=new PasswordBox{MaxLength=1024,MinHeight=36,Padding=new Thickness(10,7,10,7),Margin=new Thickness(0,5,0,5)};body.Children.Add(Text("控制密钥（留空表示使用无密钥接口；点击保存才替换）",12));password.SetResourceReference(Control.BackgroundProperty,"DeskBase");password.SetResourceReference(Control.ForegroundProperty,"DeskEditText");password.SetResourceReference(Control.BorderBrushProperty,"DeskLine");body.Children.Add(password);var state=Text(assistant.SplitHistory.Status,12);body.Children.Add(state);Button(body,"保存控制地址与密钥",()=>{ClashTrafficSource.Address(address.Text.Trim());assistant.SplitHistory.SaveKey(address.Text.Trim(),password.Password);SaveMonitor(()=>cfg.ClashController=address.Text.Trim());password.Clear();state.Text="已加密绑定本机账户保存，未修改Clash配置。";});Button(body,"检查本机统计连接",async()=>{state.Text="正在检查…";await System.Threading.Tasks.Task.Run(()=>assistant.SplitHistory.Fetch(cfg.ClashController,DateTime.UtcNow));state.Text=assistant.SplitHistory.Status;});SettingDescription(body,"在FlClash设置中查看外部控制地址与密钥。只读GET /connections，不改路由或代理；仅允许回环地址，不跟随重定向，不启用系统权限。密钥加密保存在本机用户目录，不写入assistant.json或导出图表。网卡用量与Clash内核用量属于不同来源，不相加。");
